'use strict';

const logger = require('../logger');
const { ApiError, errorResponse, validationFailed, notFound, internalError } = require('../errors');
const { requireSession, loadUserForSession, assertUserAllowed } = require('../auth');

function parseBody(event) {
    const raw = event && event.body;
    if (raw === undefined || raw === null || raw === '') return null;
    const text = event.isBase64Encoded ? Buffer.from(raw, 'base64').toString('utf8') : raw;
    try {
        return JSON.parse(text);
    } catch (err) {
        throw validationFailed([{ field: 'body', message: 'Request body must be valid JSON' }], 'Request body must be valid JSON');
    }
}

/**
 * Wraps a route handler. fn receives { event, body, session, user, context } and returns an API
 * Gateway response. With auth (default), before the body is parsed: session check, current user
 * record (401 if gone), temporary-password gate (401 expired / 403 PASSWORD_CHANGE_REQUIRED unless
 * allowTemporaryPassword), then adminOnly (a member gets 404 NOT_FOUND). ApiError becomes its error
 * response; anything else is logged and becomes 500 INTERNAL_ERROR.
 */
function withHandler(fn, { auth = true, adminOnly = false, allowTemporaryPassword = false } = {}) {
    return async (event, context) => {
        try {
            let session = null;
            let user = null;
            if (auth) {
                session = await requireSession(event);
                user = await loadUserForSession(session);
                assertUserAllowed(user, { allowTemporaryPassword });
                if (adminOnly && !user.isAdmin) throw notFound();
            }
            const body = parseBody(event);
            return await fn({ event, body, session, user, context });
        } catch (err) {
            if (err instanceof ApiError) {
                if (err.status >= 500) logger.error('request failed', { code: err.code });
                return errorResponse(err);
            }
            logger.error('unhandled error', {
                errorName: err && err.name,
                errorMessage: err && err.message,
                path: event && event.resource,
                method: event && event.httpMethod,
            });
            return errorResponse(internalError());
        }
    };
}

module.exports = { withHandler, parseBody };
